using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace MaritimeLegend {
// Immediate-layout facade backed by actual, interactive Unity uGUI components.
// The same Canvas is used for normal play and camera RenderTexture verification.
public static class LiveGui {
 public static Color color=Color.white,backgroundColor=Color.white; public static bool enabled=true; public static Matrix4x4 matrix=Matrix4x4.identity;
 class Node {public GameObject go;public RectTransform rect;public Text label;public RawImage image;public Button button;public InputField input;public Slider slider;public ScrollRect scroll;public RectTransform content;public string key;public Vector2 previousScroll;}
 static Canvas canvas;static RectTransform root,current;static Camera camera;static Dictionary<string,List<Node>> pools=new Dictionary<string,List<Node>>();static Dictionary<string,int> counts=new Dictionary<string,int>();static HashSet<string> clicks=new HashSet<string>();static Stack<RectTransform> parents=new Stack<RectTransform>();static Font font;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
 static void ResetSession(){canvas=null;root=null;current=null;camera=null;font=null;pools.Clear();counts.Clear();clicks.Clear();parents.Clear();color=Color.white;backgroundColor=Color.white;enabled=true;matrix=Matrix4x4.identity;}
 public static Camera Camera{get{return camera;}}
 public static void Initialize(Font f,bool offscreen,Transform owner){if(canvas!=null)return;font=f;camera=UnityEngine.Object.FindAnyObjectByType<Camera>();if(camera==null)camera=new GameObject("InterfaceCamera").AddComponent<Camera>();camera.transform.SetParent(owner,false);if(camera.GetComponent<AudioListener>()==null)camera.gameObject.AddComponent<AudioListener>();camera.orthographic=true;camera.orthographicSize=5;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.transform.position=new Vector3(0,0,-10);if(offscreen){camera.targetTexture=new RenderTexture(1920,1080,24,RenderTextureFormat.ARGB32);camera.targetTexture.Create();}
 var go=new GameObject("MaritimeCanvas",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(owner,false);canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=5;var scaler=go.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;root=go.GetComponent<RectTransform>();current=root;
 if(UnityEngine.Object.FindAnyObjectByType<EventSystem>()==null)new GameObject("MaritimeEventSystem",typeof(EventSystem),typeof(StandaloneInputModule)).transform.SetParent(owner,false);}
 public static void Begin(){foreach(var key in pools.Keys)counts[key]=0;current=root;parents.Clear();matrix=Matrix4x4.identity;color=Color.white;enabled=true;}
 public static void End(){foreach(var pair in pools){int used=counts.ContainsKey(pair.Key)?counts[pair.Key]:0;for(int i=used;i<pair.Value.Count;i++)pair.Value[i].go.SetActive(false);}clicks.Clear();}
 static RectTransform Child(string name,Transform parent){var go=new GameObject(name,typeof(RectTransform));var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(.5f,.5f);return r;}
 static Node Get(string kind){if(!pools.ContainsKey(kind)){pools[kind]=new List<Node>();counts[kind]=0;}int index=counts[kind]++;Node n;if(index>=pools[kind].Count){n=new Node();n.rect=Child(kind+index,root);n.go=n.rect.gameObject;switch(kind){case "image":n.image=n.go.AddComponent<RawImage>();n.image.raycastTarget=false;break;case "label":n.label=n.go.AddComponent<Text>();n.label.raycastTarget=false;break;case "button":{var image=n.go.AddComponent<Image>();image.color=new Color(.18f,.3f,.32f);n.button=n.go.AddComponent<Button>();n.button.targetGraphic=image;var text=Child("Caption",n.rect);Stretch(text);n.label=text.gameObject.AddComponent<Text>();n.label.raycastTarget=false;n.label.alignment=TextAnchor.MiddleCenter;var captured=n;n.button.onClick.AddListener(()=>clicks.Add(captured.key));break;}case "input":{n.go.AddComponent<Image>().color=new Color(.13f,.2f,.22f);var text=Child("Value",n.rect);Stretch(text);n.label=text.gameObject.AddComponent<Text>();n.label.raycastTarget=false;n.input=n.go.AddComponent<InputField>();n.input.textComponent=n.label;n.input.lineType=InputField.LineType.SingleLine;break;}case "slider":{n.go.AddComponent<Image>().color=new Color(.2f,.26f,.27f);var fill=Child("Fill",n.rect);Stretch(fill);fill.gameObject.AddComponent<Image>().color=new Color(.75f,.62f,.35f);var handle=Child("Handle",n.rect);handle.sizeDelta=new Vector2(18,26);handle.gameObject.AddComponent<Image>().color=new Color(.94f,.85f,.64f);n.slider=n.go.AddComponent<Slider>();n.slider.fillRect=fill;n.slider.handleRect=handle;n.slider.targetGraphic=handle.GetComponent<Image>();n.slider.direction=Slider.Direction.LeftToRight;break;}case "scroll":{n.go.AddComponent<RectMask2D>();n.scroll=n.go.AddComponent<ScrollRect>();n.content=Child("Content",n.rect);n.content.pivot=new Vector2(0,1);n.content.anchoredPosition=Vector2.zero;n.scroll.content=n.content;n.scroll.viewport=n.rect;n.scroll.horizontal=false;n.scroll.vertical=true;n.scroll.scrollSensitivity=38;n.scroll.movementType=ScrollRect.MovementType.Clamped;break;}}pools[kind].Add(n);}else n=pools[kind][index];n.go.SetActive(true);n.rect.SetParent(current,false);n.rect.SetAsLastSibling();n.key=kind+index;return n;}
 static void Stretch(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.offsetMin=new Vector2(9,3);r.offsetMax=new Vector2(-9,-3);}
 static void Place(Node n,Rect rect){Vector3 center=matrix.MultiplyPoint3x4(new Vector3(rect.center.x,rect.center.y,0));float sx=new Vector2(matrix.m00,matrix.m10).magnitude,sy=new Vector2(matrix.m01,matrix.m11).magnitude;n.rect.anchorMin=n.rect.anchorMax=new Vector2(0,1);n.rect.pivot=new Vector2(.5f,.5f);n.rect.anchoredPosition=new Vector2(center.x,-center.y);n.rect.sizeDelta=new Vector2(rect.width*sx,rect.height*sy);n.rect.localRotation=Quaternion.Euler(0,0,-Mathf.Atan2(matrix.m10,matrix.m00)*Mathf.Rad2Deg);n.rect.localScale=Vector3.one;bool masked=current!=root;foreach(var graphic in n.go.GetComponentsInChildren<MaskableGraphic>(true)){graphic.maskable=masked;if(!masked)graphic.canvasRenderer.cull=false;}}
 static void TextStyle(Text t,GUIStyle style){t.font=style.font!=null?style.font:font;t.fontSize=style.fontSize>0?style.fontSize:24;t.color=style.normal.textColor;t.alignment=style.alignment;t.horizontalOverflow=style.wordWrap?HorizontalWrapMode.Wrap:HorizontalWrapMode.Overflow;t.verticalOverflow=VerticalWrapMode.Truncate;t.supportRichText=false;}
 public static void DrawTexture(Rect rect,Texture texture,ScaleMode mode=ScaleMode.StretchToFill){if(texture==null)return;if(mode==ScaleMode.ScaleToFit){float ratio=(float)texture.width/texture.height;if(rect.width/rect.height>ratio){float w=rect.height*ratio;rect.x+=(rect.width-w)/2;rect.width=w;}else{float h=rect.width/ratio;rect.y+=(rect.height-h)/2;rect.height=h;}}var n=Get("image");Place(n,rect);n.image.texture=texture;n.image.color=color;n.image.uvRect=new Rect(0,0,1,1);if(mode==ScaleMode.ScaleAndCrop){float a=rect.width/rect.height,b=(float)texture.width/texture.height;if(b>a){float w=a/b;n.image.uvRect=new Rect((1-w)/2,0,w,1);}else{float h=b/a;n.image.uvRect=new Rect(0,(1-h)/2,1,h);}}}
 public static void Label(Rect rect,string value,GUIStyle style){var n=Get("label");Place(n,rect);n.label.text=value;TextStyle(n.label,style);}
 public static bool Button(Rect rect,string value,GUIStyle style){var n=Get("button");Place(n,rect);TextStyle(n.label,style);n.label.text=value;n.button.interactable=enabled;n.go.GetComponent<Image>().color=enabled?backgroundColor:new Color(.12f,.15f,.16f);n.label.color=enabled?new Color(.95f,.94f,.85f):new Color(.45f,.5f,.48f);n.key+="|"+value;return enabled&&clicks.Remove(n.key);}
 public static string TextField(Rect rect,string value,int limit,GUIStyle style){var n=Get("input");Place(n,rect);TextStyle(n.label,style);n.label.color=Color.white;n.input.interactable=enabled;n.input.characterLimit=limit;if(!n.input.isFocused)n.input.SetTextWithoutNotify(value);return n.input.text;}
 public static float HorizontalSlider(Rect rect,float value,float min,float max){var n=Get("slider");Place(n,rect);n.slider.interactable=enabled;n.slider.minValue=min;n.slider.maxValue=max;bool held=EventSystem.current!=null&&EventSystem.current.currentSelectedGameObject==n.go&&Input.GetMouseButton(0);if(!held)n.slider.SetValueWithoutNotify(value);return n.slider.value;}
 public static Vector2 BeginScrollView(Rect viewport,Vector2 scroll,Rect content){var n=Get("scroll");Place(n,viewport);n.content.sizeDelta=new Vector2(content.width,Math.Max(content.height,viewport.height));if((scroll-n.previousScroll).sqrMagnitude>.01f)n.content.anchoredPosition=new Vector2(-scroll.x,scroll.y);Vector2 result=new Vector2(-n.content.anchoredPosition.x,n.content.anchoredPosition.y);n.previousScroll=result;parents.Push(current);current=n.content;return result;}
 public static void EndScrollView(){current=parents.Pop();}
 public static Vector2 Mouse {get{return new Vector2(Input.mousePosition.x*1920/Screen.width,1080-Input.mousePosition.y*1080/Screen.height);}}
 public static bool PointerOverControl{get{return EventSystem.current!=null&&EventSystem.current.IsPointerOverGameObject();}}
 public static bool ClickText(string prefix){if(!pools.ContainsKey("button"))return false;foreach(var n in pools["button"]){if(n.go.activeInHierarchy&&n.button.interactable&&n.label.text.StartsWith(prefix,StringComparison.Ordinal)){if(n.button.targetGraphic.canvasRenderer.cull){Debug.LogError("UI_BUTTON_CULLED "+prefix);return false;}n.button.onClick.Invoke();return true;}}return false;}
 public static void Capture(string path){Canvas.ForceUpdateCanvases();var previous=RenderTexture.active;var target=camera.targetTexture;if(target==null)return;camera.Render();RenderTexture.active=target;var t=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,target.width,target.height),0,0);t.Apply();System.IO.File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.Destroy(t);RenderTexture.active=previous;}
}
public static class LiveGuiUtility {public static void RotateAroundPivot(float angle,Vector2 pivot){LiveGui.matrix=LiveGui.matrix*Matrix4x4.Translate(pivot)*Matrix4x4.Rotate(Quaternion.Euler(0,0,angle))*Matrix4x4.Translate(-pivot);}}
}
